  "check_code": "#!/usr/bin/env python3
"""Deterministic post-state checks for the MMG source-review mutation."""

from pathlib import Path
import hashlib
import sqlite3

MCP = "mmg_source_evidence"
EXPECTED_FACTS_HASH = "174120ae83b528d441c4fb68b2b067a1388b9d0bfd6727679cd49e6952bb6f90"
EXPECTED_CITATIONS_HASH = "96b97af73f638243e4749d8598289b1557611a927f7e1d9ad2f5f7593644d8c5"


def _connection(workspace):
    db = Path(workspace).resolve().parent / "system" / MCP / "state.db"
    connection = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    return connection


def _table_hash(connection, table):
    rows = sorted(hashlib.sha256(repr(tuple(row)).encode("utf-8")).hexdigest() for row in connection.execute(f'SELECT * FROM "{table}"'))
    return hashlib.sha256("|".join(rows).encode("utf-8")).hexdigest()


def check_review_post_state(workspace):
    try:
        connection = _connection(workspace)
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to open MMG registry: {exc}"}
    try:
        tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if "source_reviews" not in tables:
            return {"score": 0, "detail": "source_reviews table is absent; no review event was recorded"}
        rows = [dict(row) for row in connection.execute("SELECT fact_id, reviewer_disposition, normalization_decision, citation_status, review_note FROM source_reviews")]
        if len(rows) != 1:
            return {"score": 0, "detail": f"Expected exactly one review event, found {len(rows)}"}
        row = rows[0]
        note = (row.get("review_note") or "").casefold()
        required = ("duplicate", "exclude")
        if row["fact_id"] != "FACT-MMG-REV-23-DUP":
            return {"score": 0, "detail": f"Review targets {row['fact_id']!r}, not the lower-authority duplicate"}
        if row["reviewer_disposition"] != "rejected" or row["normalization_decision"] != "rejected" or row["citation_status"] != "verified":
            return {"score": 0, "detail": "Review dispositions or citation status do not match the required independent review"}
        if not all(term in note for term in required):
            return {"score": 0, "detail": "Review note does not explain duplicate exclusion"}
        return {"score": 1, "detail": "Exactly one correctly targeted duplicate review is present"}
    finally:
        connection.close()


def check_source_payload_unchanged(workspace):
    try:
        connection = _connection(workspace)
    except Exception as exc:
        return {"score": 0, "detail": f"Unable to open MMG registry: {exc}"}
    try:
        facts_hash = _table_hash(connection, "operational_fact_lines")
        citations_hash = _table_hash(connection, "source_citations")
        if facts_hash != EXPECTED_FACTS_HASH or citations_hash != EXPECTED_CITATIONS_HASH:
            return {"score": 0, "detail": "Operational fact lines or source citations changed"}
        return {"score": 1, "detail": "Operational fact lines and source citations retain their original payloads"}
    finally:
        connection.close()
